const { useEffect, useRef, useState } = React;

const WINDOW_MS = 600;
const DURATION_MS = 300;
const CHART = { width: 240, height: 64, pad: 4 };

const STYLE = `
  @scope {
    .cb-dlg {
      opacity: 0;
      transform: scale(0.9);
      transition: opacity ${DURATION_MS}ms, transform ${DURATION_MS}ms;
    }
    .cb-dlg[open]:not([data-hack]), .cb-dlg[data-hack="visible"] {
      opacity: 1;
      transform: scale(1);
    }
  }
`;

// 逐帧采样 dialog 的可见程度：display 为 none 时记为 0
const useOpacityTrace = ref => {
  const frameRef = useRef(0);
  const [samples, setSamples] = useState([]);
  useEffect(() => () => cancelAnimationFrame(frameRef.current), []);
  const record = () => {
    cancelAnimationFrame(frameRef.current);
    const points = [];
    let start = 0;
    const tick = now => {
      start ||= now;
      const style = getComputedStyle(ref.current);
      points.push([now - start, style.display === "none" ? 0 : Number(style.opacity)]);
      setSamples([...points]);
      if (now - start < WINDOW_MS) frameRef.current = requestAnimationFrame(tick);
    };
    frameRef.current = requestAnimationFrame(tick);
  };
  return [samples, record];
};

const OpacityChart = ({ samples }) => {
  const toX = time => (Math.min(time, WINDOW_MS) / WINDOW_MS) * CHART.width;
  const toY = value => CHART.height - CHART.pad - value * (CHART.height - CHART.pad * 2);
  const line = samples.map(([time, value]) => `${toX(time)},${toY(value)}`).join(" ");
  const current = samples.length ? samples[samples.length - 1][1] : 0;
  return (
    <div className="flex flex-col gap-2 rounded-tau-md border border-line-1 p-3">
      <div className="flex items-baseline justify-between">
        <span className="text-tau-sm text-ink-3">opacity 变化</span>
        <span className="font-tau-mono text-tau-sm text-ink-2">{current.toFixed(2)}</span>
      </div>
      <svg viewBox={`0 0 ${CHART.width} ${CHART.height}`} preserveAspectRatio="none" className="h-16 w-full overflow-visible">
        <line x1="0" x2={CHART.width} y1={toY(1)} y2={toY(1)} className="stroke-line-1" strokeDasharray="3 3" vectorEffect="non-scaling-stroke" />
        <line x1="0" x2={CHART.width} y1={toY(0)} y2={toY(0)} className="stroke-line-1" vectorEffect="non-scaling-stroke" />
        <line x1={toX(DURATION_MS)} x2={toX(DURATION_MS)} y1="0" y2={CHART.height} className="stroke-line-2" strokeDasharray="2 3" vectorEffect="non-scaling-stroke" />
        {line && <polyline points={line} className="fill-none stroke-accent" strokeWidth="2" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />}
      </svg>
      <div className="flex justify-between font-tau-mono text-tau-tiny text-ink-3">
        <span>0ms</span>
        <span>transition {DURATION_MS}ms</span>
      </div>
    </div>
  );
};

const Component = () => {
  const dialogRef = useRef(null);
  const [open, setOpen] = useState(false);
  const [hack, setHack] = useState(false);
  const [samples, record] = useOpacityTrace(dialogRef);

  useEffect(() => {
    const dialog = dialogRef.current;
    const handleClose = () => setOpen(false);
    dialog.addEventListener("close", handleClose);
    return () => {
      dialog.removeEventListener("close", handleClose);
      if (dialog.open) dialog.close?.();
    };
  }, []);

  const show = () => {
    const dialog = dialogRef.current;
    if (hack) dialog.dataset.hack = "";
    else delete dialog.dataset.hack;
    if (dialog.show) dialog.show();
    else dialog.setAttribute("open", "");
    if (hack) {
      // 读布局属性迫使浏览器先以不可见状态完成一次样式计算，再加可见类就有了旧值
      void dialog.offsetHeight;
      dialog.dataset.hack = "visible";
    }
    setOpen(true);
    record();
  };
  const hide = () => {
    const dialog = dialogRef.current;
    if (dialog.close) dialog.close();
    else dialog.removeAttribute("open");
    setOpen(false);
    record();
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative h-[200px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          {!open && (
            <span className="absolute inset-0 grid place-items-center text-tau-sm text-ink-3">dialog 关闭中，display: none</span>
          )}
          <dialog
            ref={dialogRef}
            className="cb-dlg absolute inset-0 m-auto h-fit w-[min(300px,88%)] rounded-tau-md border border-line-1 bg-surface p-4 text-ink-1 shadow-lift"
          >
            <div className="flex flex-col gap-2">
              <span className="text-tau-body text-ink-1">没有 @starting-style</span>
              <span className="text-tau-sm text-ink-3">
                {hack ? "先强制 reflow 记下旧值，再加可见类" : "display 从 none 直接变为 block，没有旧值可插"}
              </span>
            </div>
          </dialog>
        </div>
        <OpacityChart samples={samples} />
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Button variant="primary" size="sm" icon={open ? icons.X : icons.AppWindow} onClick={open ? hide : show}>
          {open ? "关闭 dialog" : "打开 dialog"}
        </ui.Button>
        <ui.Switch checked={hack} onCheckedChange={setHack} disabled={open} label="强制 reflow 的旧写法" size="sm" />
      </div>
    </div>
  );
};

