  @scope {
    .cb-dlg {
      opacity: 0;
      transform: scale(0.9);
      transition: opacity ${DURATION_MS}ms, transform ${DURATION_MS}ms${discrete ? `, display ${DURATION_MS}ms allow-discrete` : ""};
