const Component = () => {
  const dialogRef = useRef(null);
  const [open, setOpen] = useState(false);
  const [starting, setStarting] = useState(true);
  const [discrete, setDiscrete] = useState(true);
  const [samples, record] = useOpacityTrace(dialogRef);

  useEffect(() => {
    const dialog = dialogRef.current;
    return () => {
      if (dialog.open) dialog.close?.();
    };
  }, []);

  const toggle = () => {
    const dialog = dialogRef.current;
    if (open) {
      if (dialog.close) dialog.close();
      else dialog.removeAttribute("open");
    } else if (dialog.show) dialog.show();
    else dialog.setAttribute("open", "");
    setOpen(!open);
    record();
  };

  const flags = { starting, discrete };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{buildStyle(starting, discrete)}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="relative h-[200px] min-w-0 overflow-hidden rounded-tau-md border border-line-1">
          <dialog
            ref={dialogRef}
            className="cb-dlg absolute inset-0 m-auto h-fit w-[min(300px,88%)] rounded-tau-md border border-line-1 bg-surface p-4 text-ink-1 shadow-lift"
          >
            <div className="flex flex-col gap-2">
              <span className="text-tau-body text-ink-1">{starting ? "入场有首帧样式" : "入场没有首帧样式"}</span>
              <span className="text-tau-sm text-ink-3">{discrete ? "退场播完后 display 才变为 none" : "退场时 display 立即变为 none"}</span>
            </div>
          </dialog>
        </div>
        <OpacityChart samples={samples} />
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        {codeLines(discrete).map((line, index) => (
          <div
            key={index}
            className={
              !line.flag ? "" : flags[line.flag] ? "rounded-tau-sm bg-accent-soft text-accent-text" : "text-ink-3 line-through"
            }
          >
            {line.text}
          </div>
        ))}
      </pre>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Button variant="primary" size="sm" icon={open ? icons.X : icons.AppWindow} onClick={toggle}>
          {open ? "关闭 dialog" : "打开 dialog"}
        </ui.Button>
        <ui.Switch checked={starting} onCheckedChange={setStarting} label="@starting-style" size="sm" />
        <ui.Switch checked={discrete} onCheckedChange={setDiscrete} label="allow-discrete" size="sm" />
      </div>
    </div>
  );
};

