const { useEffect, useRef, useState } = React;

const EXIT_MS = 400;

const buildStyle = starting => `
  @scope {
    .cb-item {
      opacity: 1;
      transform: translateX(0);
      transition: opacity ${EXIT_MS}ms, transform ${EXIT_MS}ms;
      ${starting ? "@starting-style { opacity: 0; transform: translateX(-20px); }" : ""}
    }
    .cb-item[data-leaving] {
      opacity: 0;
      transform: translateX(20px);
    }
  }
`;

const Component = () => {
  const nextIdRef = useRef(3);
  const timersRef = useRef(new Set());
  const [items, setItems] = useState([{ id: 1 }, { id: 2 }]);
  const [starting, setStarting] = useState(true);
  const [exitAnimation, setExitAnimation] = useState(false);

  useEffect(() => () => timersRef.current.forEach(clearTimeout), []);

  const add = () => {
    const id = nextIdRef.current++;
    setItems(current => [...current, { id }]);
  };

  const drop = id => setItems(current => current.filter(item => item.id !== id));

  // 没有 @ending-style：先标记退场让过渡跑完，再真正移出 DOM
  const remove = id => {
    if (!exitAnimation) return drop(id);
    setItems(current => current.map(item => (item.id === id ? { ...item, leaving: true } : item)));
    const timer = setTimeout(() => {
      timersRef.current.delete(timer);
      drop(id);
    }, EXIT_MS);
    timersRef.current.add(timer);
  };

  return (
    <div className="@container flex flex-col gap-3">
      <style>{buildStyle(starting)}</style>
      <div className="flex min-h-[200px] flex-col gap-2 rounded-tau-md border border-line-1 p-3">
        {items.length === 0 && (
          <span className="m-auto text-tau-sm text-ink-3">列表为空</span>
        )}
        {items.map(item => (
          <div
            key={item.id}
            data-leaving={item.leaving || undefined}
            className="cb-item flex items-center gap-3 rounded-tau-sm border border-line-1 bg-surface py-1.5 pl-3 pr-1.5"
          >
            <span className="grid size-5 shrink-0 place-items-center rounded-full bg-hover font-tau-mono text-tau-tiny text-ink-2">
              {item.id}
            </span>
            <span className="min-w-0 flex-1 truncate text-tau-body text-ink-1">第 {item.id} 项</span>
            <ui.IconButton aria-label={`移除第 ${item.id} 项`} disabled={item.leaving} onClick={() => remove(item.id)}>
              <icons.X className="size-4" />
            </ui.IconButton>
          </div>
        ))}
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.Button variant="primary" size="sm" icon={icons.Plus} onClick={add}>
          添加一项
        </ui.Button>
        <ui.Switch checked={starting} onCheckedChange={setStarting} label="@starting-style" size="sm" />
        <ui.Switch checked={exitAnimation} onCheckedChange={setExitAnimation} label="移除前先播退场" size="sm" />
      </div>
    </div>
  );
};

